#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_1 17
#define RELAY_2 22
#define RELAY_3 23
#define RELAY_4 24

void sigint_handler(int signum)
{
    printf("SIGINT received, exiting...\n");
    gpioWrite(RELAY_1, 0);
    gpioWrite(RELAY_2, 0);
    gpioWrite(RELAY_3, 0);
    gpioWrite(RELAY_4, 0);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum)
{
    printf("SIGTERM received, exiting...\n");
    gpioWrite(RELAY_1, 0);
    gpioWrite(RELAY_2, 0);
    gpioWrite(RELAY_3, 0);
    gpioWrite(RELAY_4, 0);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        printf("gpioInitialise() failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    while (1)
    {
        gpioWrite(RELAY_1, 1);
        sleep(1);
        gpioWrite(RELAY_1, 0);
        sleep(1);

        gpioWrite(RELAY_2, 1);
        sleep(1);
        gpioWrite(RELAY_2, 0);
        sleep(1);

        gpioWrite(RELAY_3, 1);
        sleep(1);
        gpioWrite(RELAY_3, 0);
        sleep(1);

        gpioWrite(RELAY_4, 1);
        sleep(1);
        gpioWrite(RELAY_4, 0);
        sleep(1);
    }

    return 0;
}

