#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>

int main(void)
{
    int servo1 = 7;
    int servo2 = 8;
    int servo3 = 9;
    int servo4 = 10;
    int servo5 = 11;

    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(servo1, PI_OUTPUT);
    gpioSetMode(servo2, PI_OUTPUT);
    gpioSetMode(servo3, PI_OUTPUT);
    gpioSetMode(servo4, PI_OUTPUT);
    gpioSetMode(servo5, PI_OUTPUT);

    gpioServo(servo1, 1000);
    gpioServo(servo2, 1500);
    gpioServo(servo3, 2000);
    gpioServo(servo4, 500);
    gpioServo(servo5, 2500);

    sleep(3);

    gpioServo(servo1, 0);
    gpioServo(servo2, 0);
    gpioServo(servo3, 0);
    gpioServo(servo4, 0);
    gpioServo(servo5, 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}
